-- Translations.
--
-- Player-facing text is written in English in the code and looked up in ns.L:
-- L["Lock In"] is the client language's version of "Lock In", or the English
-- when there is none. Data with text (cards, opponents, keywords, the
-- tutorial) goes through L where it is defined, the same way.
--
-- Each language has a file, Locales/<code>.lua, that fills L when the client
-- uses that language. Locales/enUS.lua is the translators' template: every
-- key, with notes, generated by `python tests/run_tests.py locale write`;
-- `python tests/run_tests.py locale` checks every language file against it.
-- Pure Lua, no WoW API calls beyond GetLocale, so the engine can use it.
local _, ns = ...

local client = (GetLocale and GetLocale()) or "enUS"
if client == "enGB" then client = "enUS" end
ns.LOCALE = client

local L = setmetatable({}, { __index = function(_, k) return k end })
ns.L = L

-- For a language file: L if the client uses one of these languages, else nil
-- (the file then returns without doing anything).
function ns.NewLocale(...)
  for i = 1, select("#", ...) do
    if select(i, ...) == client then return L end
  end
end

-- The pattern for n things: ns.Plural(n, "%d card pack", "%d card packs").
-- Format it yourself. Languages with more than two forms translate both keys
-- with wording that works for any number ("Card packs: %d").
function ns.Plural(n, one, other)
  if n == 1 then return L[one] end
  return L[other]
end
